<?php
declare(strict_types=1);
namespace App;
final class UserController {
 public static function index():string {RoleService::admin();if($_SERVER['REQUEST_METHOD']==='POST'){Http::checkCsrf();UserService::save((int)($_POST['id']??0)?:null,$_POST);Http::redirect('/users');}$q=trim((string)($_GET['q']??''));$query=DB::pdo()->prepare('SELECT u.*,r.name role_label FROM users u JOIN roles r ON r.id=u.role WHERE u.username LIKE ? OR u.name LIKE ? ORDER BY u.id');$query->execute(['%'.$q.'%','%'.$q.'%']);$rows=$query->fetchAll();$s=str_replace('<div class="page-head-actions"></div>','<div class="page-head-actions"><button type="button" class="btn btn-primary" data-open-form="/settings/users/new">Добавить пользователя</button></div>',View::heading('Пользователи','','users-group'));$s.='<section class="table-card registry-ui-card registry-ui-sticky-table registry-ui-sticky-table--wide-scroll registry-ui-scroll" data-registry-id="system-users" data-registry-view><div class="table-toolbar registry-ui-toolbar"><span class="found-label">Найдено: <b data-result-count>'.count($rows).'</b></span><form class="toolbar-right" method="get" data-search-form><input type="search" class="registry-ui-search" name="q" value="'.View::e($q).'" placeholder="Поиск по таблице" aria-label="Поиск по таблице" data-live-search></form></div><div class="table-scroll" role="region" aria-label="Пользователи: прокрутка таблицы" tabindex="0"><table class="table registry-ui-table registry-ui-data registry-ui-data--columns"><thead><tr><th class="registry-ui-id">ID</th><th>Пользователь</th><th>Логин</th><th>Роль</th><th>Статус</th></tr></thead><tbody>';foreach($rows as $u)$s.='<tr tabindex="0" data-record-url="/settings/users/edit?id='.$u['id'].'" aria-label="Открыть '.View::e($u['name']).'"><td class="registry-ui-id">'.$u['id'].'</td><td><span class="registry-ui-name">'.View::e($u['name']).'</span></td><td><span class="registry-ui-primary">'.View::e($u['username']).'</span></td><td>'.View::e($u['role_label']).'</td><td><span class="badge '.($u['active']?'badge-ok':'badge-neutral').'">'.($u['active']?'Активен':'Отключён').'</span></td></tr>';return View::page('Пользователи',$s.'</tbody></table></div><div data-pagination></div></section>');}
 public static function edit(bool $new=false):string {RoleService::admin();$id=$new?null:(int)($_GET['id']??0);$u=['username'=>'','name'=>'','role'=>'viewer','active'=>1,'version'=>1];if($id){$q=DB::pdo()->prepare('SELECT id,username,name,role,active,version FROM users WHERE id=?');$q->execute([$id]);$u=$q->fetch()?:throw new \RuntimeException('Пользователь не найден.',404);}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){Http::checkCsrf();try{UserService::save($id,$_POST);Http::redirect('/users');}catch(\RuntimeException $e){if(!in_array($e->getCode(),[409,422],true))throw $e;$error='<div class="form-alert alert-error" role="alert"><span class="alert-mark">×</span><div class="alert-body"><div class="alert-body-title">'.View::e($e->getMessage()).'</div></div></div>';}}
 $title=$new?'Добавить пользователя':'Изменить пользователя';$action=$new?'/settings/users/new':'/settings/users/edit?id='.$id;$s='<div data-editor-fragment data-editor-title="'.$title.'"><form method="post" action="'.$action.'" id="user-form" class="registry-ui-modal-grid"><input type="hidden" name="_csrf" value="'.View::e(Http::csrf()).'"><input type="hidden" name="expected_revision" value="'.View::e($_POST['expected_revision']??$u['version']).'">'.$error.'<div class="registry-ui-modal-grid registry-ui-modal-grid--reading">';foreach(['username'=>['Логин','text'],'display_name'=>['Имя','text'],'new_password'=>['Новый пароль','password'],'confirm_password'=>['Повторите пароль','password']]as $field=>[$label,$type]){$value=$type==='password'?'':($_POST[$field]??$u[$field==='display_name'?'name':$field]??'');$s.='<div class="field"><label class="field-label" for="user-'.$field.'">'.$label.'</label><input class="field-input" id="user-'.$field.'" name="'.$field.'" type="'.$type.'" value="'.View::e($value).'"'.($type==='password'?' autocomplete="new-password"'.($new?' required':''):' required').'>'.($field==='new_password'?'<span class="registry-ui-modal-help">'.($new?'Не менее 12 символов.':'От 12 символов. Пусто — без смены пароля.').'</span>':'').'</div>';}$s.='<div class="field"><label class="field-label" for="user-role">Роль</label><select class="field-select" name="role" id="user-role">';foreach(DB::pdo()->query('SELECT id,name FROM roles ORDER BY name')as $r)$s.='<option value="'.View::e($r['id']).'"'.(($r['id']===($_POST['role']??$u['role']))?' selected':'').'>'.View::e($r['name']).'</option>';$s.='</select></div><div class="field"><label><input type="checkbox" name="is_active"'.(($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['is_active']):$u['active'])?' checked':'').'> Активен</label></div></div><span class="registry-ui-modal-help">Роль задаёт права доступа. Отключённый пользователь не сможет войти.</span></form><div class="modal-foot-actions" data-editor-actions><button class="btn btn-secondary" type="button" data-editor-close>Отмена</button><button class="btn btn-primary" type="submit" form="user-form">Сохранить</button></div></div>';if(($_SERVER['HTTP_X_REQUESTED_WITH']??'')==='ERP-Fetch')return $s;preg_match('~<form\b.*?</form>~s',$s,$match);$form=str_replace('class="registry-ui-modal-grid"','class="table-card registry-ui-card demo-form-width"',$match[0]);$form=str_replace('<div class="registry-ui-modal-grid registry-ui-modal-grid--reading">','<section class="panel-section"><h2 class="section-title">Учётные данные</h2><div class="form-grid-2">',$form);$form=str_replace('</div><span class="registry-ui-modal-help">Роль задаёт права доступа. Отключённый пользователь не сможет войти.</span></form>','</div></section><section class="panel-section"><p class="registry-ui-secondary">Роль определяет доступ пользователя к страницам. Отключённый пользователь не сможет войти в систему.</p></section></form>',$form);$heading=str_replace('<div class="page-head-actions"></div>','<div class="page-head-actions"><a class="btn btn-secondary" href="/users">Отмена</a><button class="btn btn-primary" type="submit" form="user-form">Сохранить</button></div>',View::heading($title,'','user'));return View::page($title,$heading.$form);}
}
